@import './theme-first.scss';
// @import './theme-second.scss';

body {
    padding: 30px;
}

.font-primary {
    font-family: $font-primary;
}

.font-secondary {
    font-family: $font-secondary;
}

.container {
    display: flex;
    flex-direction: column;
    justify-content: center;

    .box {
        width: 200px;
        height: 100px;
        display: flex;
        align-items: flex-start;
        justify-content: flex-start;
        border: 1px solid #efefef;
        padding: 10px;
        box-sizing: border-box;
    }

    .box-primary {
        background-color: $color-primary;
    }

    .box-important {
        background-color: $color-important;
    }

    .box-warning {
        background-color: $color-warning;
    }

    .box-shadow {
        @include shadow();
    }
}

sources.theme-first.scss:
@use "sass:color";

// Colores
$color-primary: #f42727;
$color-important: color.adjust($color-primary, $lightness: -20%);
$color-warning: color.adjust($color-primary, $lightness: 20%);

// Fuentes
$font-primary: 'Courier New', monospace;
$font-secondary: 'Arial', sans-serif;

// Shadow mixin

@mixin shadow() {
  box-shadow: -4px 4px 10px rgba(0, 0, 0, 0.3);
}
